INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, raw_content) VALUES (1052, 'Rentas de segunda categoría (venta de inmuebles y valores mobiliarios)', 'https://www.gob.pe/8247-rentas-de-segunda-categoria-venta-de-inmuebles-y-valores-mobiliarios', 'SUNAT', '# Entidad: SUNAT
