INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, raw_content) VALUES (1059, 'Emitir comprobante de pago por rentas de alquileres', 'https://www.gob.pe/1185-emitir-comprobante-de-pago-por-rentas-de-alquileres', 'SUNAT', '# Entidad: SUNAT
