INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, raw_content) VALUES (1215, 'Consultar declaraciones de predios en la Sunat', 'https://www.gob.pe/16656-consultar-declaraciones-de-predios-en-la-sunat', 'SUNAT', '# Entidad: SUNAT
