INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, raw_content) VALUES (1261, 'Ampliación de la autorización para el ingreso y salida del territorio nacional de mercurio, cianuro de sodio, cianuro de potasio e hidrocarburos', 'https://www.gob.pe/20523-ampliacion-de-la-autorizacion-para-el-ingreso-y-salida-del-territorio-nacional-de-mercurio-cianuro-de-sodio-cianuro-de-potasio-e-hidrocarburos', 'SUNAT', '# Entidad: SUNAT
## Trámite: Ampliación de la autorización para el ingreso y salida del territorio nacional de mercurio, cianuro de sodio, cianuro de potasio e hidrocarburos
**URL Oficial:** https://www.gob.pe/20523-ampliacion-de-la-autorizacion-para-el-ingreso-y-salida-del-territorio-nacional-de-mercurio-cianuro-de-sodio-cianuro-de-potasio-e-hidrocarburos

