INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, raw_content) VALUES (1462, 'Operaciones gravadas y exoneradas del ITF', 'https://www.gob.pe/7965-operaciones-gravadas-y-exoneradas-del-itf', 'SUNAT', '# Entidad: SUNAT
