INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, raw_content) VALUES (1507, 'Pagos Sunat con Yape', 'https://www.gob.pe/36302-pagos-sunat-con-yape', 'SUNAT', '# Entidad: SUNAT
