INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, raw_content) VALUES (1527, 'Consultar reporte de ingresos', 'https://www.gob.pe/7996-consultar-reporte-de-ingresos', 'SUNAT', '# Entidad: SUNAT
