INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, raw_content) VALUES (1541, 'Consultar la plataforma Operatividad Aduanera de la Sunat', 'https://www.gob.pe/7474-consultar-la-plataforma-operatividad-aduanera-de-la-sunat', 'SUNAT', '# Entidad: SUNAT
